import json
from itertools import permutations

def solve():
    houses = [0, 1, 2, 3]  # indices for houses 1..4

    Names = ['Eric', 'Alice', 'Peter', 'Arnold']
    Smoothies = ['dragonfruit', 'cherry', 'desert', 'watermelon']
    Sports = ['soccer', 'tennis', 'basketball', 'swimming']
    Cars = ['tesla model 3', 'toyota camry', 'honda civic', 'ford f150']
    Flowers = ['daffodils', 'roses', 'lilies', 'carnations']

    for sports in permutations(Sports):
        # 4. Tennis is in the first house.
        if sports[0] != 'tennis':
            continue
        # 12. The person who loves tennis and the person who loves soccer are next to each other.
        if abs(sports.index('tennis') - sports.index('soccer')) != 1:
            continue

        for cars in permutations(Cars):
            # 5. The person who owns a Toyota Camry and the person who loves basketball are next to each other.
            if abs(cars.index('toyota camry') - sports.index('basketball')) != 1:
                continue

            for flowers in permutations(Flowers):
                # 1. The person who owns a Tesla Model 3 is the person who loves the rose bouquet.
                if flowers[cars.index('tesla model 3')] != 'roses':
                    continue
                # 7. The person who owns a Honda Civic is the person who loves a bouquet of daffodils.
                if flowers[cars.index('honda civic')] != 'daffodils':
                    continue
                # 11. The person who loves basketball is the person who loves the boquet of lilies.
                if flowers[sports.index('basketball')] != 'lilies':
                    continue

                for names in permutations(Names):
                    # 6. Arnold is the person who loves basketball.
                    if names[sports.index('basketball')] != 'Arnold':
                        continue
                    # 8. Eric is the person who loves the rose bouquet.
                    if names[flowers.index('roses')] != 'Eric':
                        continue

                    for smoothies in permutations(Smoothies):
                        # 2. Peter is the Dragonfruit smoothie lover.
                        if smoothies[names.index('Peter')] != 'dragonfruit':
                            continue
                        # 3. The Desert smoothie lover is the person who owns a Toyota Camry.
                        if smoothies[cars.index('toyota camry')] != 'desert':
                            continue
                        # 9. The Watermelon smoothie lover is not in the first house.
                        if smoothies[0] == 'watermelon':
                            continue
                        # 10. The person who owns a Honda Civic is somewhere to the right of the Desert smoothie lover.
                        if cars.index('honda civic') <= smoothies.index('desert'):
                            continue

                        solution = {
                            "solution": {
                                "header": ["House", "Name", "Smoothie", "FavoriteSport", "CarModel", "Flower"],
                                "rows": []
                            }
                        }
                        for i in houses:
                            solution["solution"]["rows"].append([
                                str(i + 1),
                                names[i],
                                smoothies[i],
                                sports[i],
                                cars[i],
                                flowers[i]
                            ])
                        return solution

    # In case no solution is found (should not happen with given constraints)
    return {
        "solution": {
            "header": ["House", "Name", "Smoothie", "FavoriteSport", "CarModel", "Flower"],
            "rows": []
        }
    }

if __name__ == "__main__":
    result = solve()
    print(json.dumps(result, ensure_ascii=False, indent=2))
